import 'destiny_api.dart';
class DestinyEntitlement { final String plan; final int credits; final DateTime? expiresAt; const DestinyEntitlement({required this.plan,required this.credits,required this.expiresAt}); bool get isPremium=>plan=='premium'; bool get isPro=>plan=='pro'||isPremium; bool get isActive=>expiresAt==null||expiresAt!.isAfter(DateTime.now()); factory DestinyEntitlement.fromMap(Map<String,dynamic> m)=>DestinyEntitlement(plan:m['plan']?.toString()??'free',credits:(m['credits'] as num?)?.toInt()??0,expiresAt:DateTime.tryParse(m['expires_at']?.toString()??'')); }
class EntitlementService { Future<DestinyEntitlement> getCurrent() async { try { return DestinyEntitlement.fromMap(await DestinyApi.instance.me()); } catch (_) { return const DestinyEntitlement(plan:'free',credits:0,expiresAt:null); } } Future<DestinyEntitlement> refresh()=>getCurrent(); }
